def svg(name: str, size: int = 20, color: str = "currentColor") -> str:
    """Return an inline SVG string for the given icon name."""
    path = _PATHS.get(name, _PATHS.get("bookmark", ""))
    return (
        f'<svg {_VB} {_XMLNS} width="{size}" height="{size}" '
        f'fill="{color}" style="vertical-align:middle;">'
        f'<path d="{path}"/></svg>'
    )
